architecture rtl of hbm_tg_ip is
  constant NPORT  : positive := 30;
  constant ADDR_W : positive := 33;
  signal arvalid, arready, rvalid, rready, rlast
       : std_logic_vector(NPORT-1 downto 0);
  -- rresp was DECLARED on every port and then dropped on the floor:
  -- the wrapper accepted it and connected nothing, so the generator
  -- counted error beats as good ones and a mis-decoded address would
  -- have reported HIGHER bandwidth, not a failure.  Now carried.
  signal rresp   : std_logic_vector(NPORT*2-1 downto 0);
  signal araddr  : std_logic_vector(NPORT*ADDR_W-1 downto 0);
  signal arlen   : std_logic_vector(NPORT*8-1 downto 0);
  signal arsize  : std_logic_vector(NPORT*3-1 downto 0);
  signal arburst : std_logic_vector(NPORT*2-1 downto 0);
  signal awvalid, awready, wvalid, wready, wlast, bvalid, bready
       : std_logic_vector(NPORT-1 downto 0);
  signal awaddr  : std_logic_vector(NPORT*ADDR_W-1 downto 0);
  signal awlen   : std_logic_vector(NPORT*8-1 downto 0);
  signal awsize  : std_logic_vector(NPORT*3-1 downto 0);
  signal awburst : std_logic_vector(NPORT*2-1 downto 0);
  signal wdata   : std_logic_vector(NPORT*256-1 downto 0);
  signal wstrb   : std_logic_vector(NPORT*32-1 downto 0);
  signal bresp   : std_logic_vector(NPORT*2-1 downto 0);
begin
  u : entity work.hbm_tg
    generic map(NPORT => NPORT, AXI_DW => 256, ADDR_W => ADDR_W,
                REGION_LOG2 => 28, PORT0 => 1)
    port map(clk => clk, rstn => rstn,
      hbm_temp0 => hbm_temp0, hbm_temp1 => hbm_temp1,
      hbm_cattrip0 => hbm_cattrip0, hbm_cattrip1 => hbm_cattrip1,
      s_awvalid => s_axi_awvalid, s_awready => s_axi_awready,
      s_awaddr  => s_axi_awaddr,
      s_wvalid  => s_axi_wvalid,  s_wready  => s_axi_wready,
      s_wdata   => s_axi_wdata,
      s_bvalid  => s_axi_bvalid,  s_bready  => s_axi_bready,
      s_arvalid => s_axi_arvalid, s_arready => s_axi_arready,
      s_araddr  => s_axi_araddr,
      s_rvalid  => s_axi_rvalid,  s_rready  => s_axi_rready,
      s_rdata   => s_axi_rdata,
      m_arvalid => arvalid, m_arready => arready, m_araddr => araddr,
      m_arlen   => arlen,   m_arsize  => arsize,  m_arburst => arburst,
      m_rvalid  => rvalid,  m_rready  => rready,  m_rlast   => rlast,
      m_rresp   => rresp,
      m_awvalid => awvalid, m_awready => awready, m_awaddr => awaddr,
      m_awlen   => awlen,   m_awsize  => awsize,  m_awburst => awburst,
      m_wvalid  => wvalid,  m_wready  => wready,  m_wdata   => wdata,
      m_wstrb   => wstrb,   m_wlast   => wlast,
      m_bvalid  => bvalid,  m_bready  => bready,  m_bresp   => bresp,
      aresetn_o => aresetn_o);

  s_axi_bresp <= "00";
  s_axi_rresp <= "00";

  -- port 0
  m00_axi_arvalid <= arvalid(0);
  arready(0) <= m00_axi_arready;
  m00_axi_araddr  <= araddr(32 downto 0);
  -- AXI3: 4-bit ARLEN.  hbm_tg's register is 8-bit and protocol
  -- agnostic; anything above 15 would silently wrap, so it is
  -- truncated HERE, where the protocol is known.
  m00_axi_arlen   <= arlen(3 downto 0);
  m00_axi_arid    <= (others => '0');
  m00_axi_arsize  <= arsize(2 downto 0);
  m00_axi_arburst <= arburst(1 downto 0);
  m00_axi_rready  <= rready(0);
  rvalid(0) <= m00_axi_rvalid;
  rlast(0)  <= m00_axi_rlast;
  rresp(1 downto 0) <= m00_axi_rresp;
  -- write channel, live as of 2026-08-25.  It was tied off while the
  -- instrument was read-only; C 2.5's 2R+1W and B's four masters
  -- are write traffic, so every number measured before this
  -- described a pattern only subsystem A issues.
  m00_axi_awvalid <= awvalid(0);
  awready(0) <= m00_axi_awready;
  m00_axi_awaddr  <= awaddr(32 downto 0);
  -- AXI3 again: 4-bit AWLEN, truncated HERE for the same reason
  -- ARLEN is.  A burst is at most 16 beats in EITHER direction.
  m00_axi_awlen   <= awlen(3 downto 0);
  m00_axi_awid    <= (others => '0');
  m00_axi_awsize  <= awsize(2 downto 0);
  m00_axi_awburst <= awburst(1 downto 0);
  m00_axi_wvalid  <= wvalid(0);
  wready(0) <= m00_axi_wready;
  m00_axi_wdata   <= wdata(255 downto 0);
  m00_axi_wstrb   <= wstrb(31 downto 0);
  m00_axi_wlast   <= wlast(0);
  bvalid(0) <= m00_axi_bvalid;
  m00_axi_bready  <= bready(0);
  bresp(1 downto 0) <= m00_axi_bresp;
  -- BID is returned and ignored: every burst uses ID 0, so there
  -- is nothing to demultiplex.  Note the HBM SAXI port has NO WID
  -- (checked against the IP's own port list, not assumed) -- it
  -- does not support write interleaving, which is exactly why one
  -- ID and in-order data is the only legal way to drive it.

  -- port 1
  m01_axi_arvalid <= arvalid(1);
  arready(1) <= m01_axi_arready;
  m01_axi_araddr  <= araddr(65 downto 33);
  -- AXI3: 4-bit ARLEN.  hbm_tg's register is 8-bit and protocol
  -- agnostic; anything above 15 would silently wrap, so it is
  -- truncated HERE, where the protocol is known.
  m01_axi_arlen   <= arlen(11 downto 8);
  m01_axi_arid    <= (others => '0');
  m01_axi_arsize  <= arsize(5 downto 3);
  m01_axi_arburst <= arburst(3 downto 2);
  m01_axi_rready  <= rready(1);
  rvalid(1) <= m01_axi_rvalid;
  rlast(1)  <= m01_axi_rlast;
  rresp(3 downto 2) <= m01_axi_rresp;
  -- write channel, live as of 2026-08-25.  It was tied off while the
  -- instrument was read-only; C 2.5's 2R+1W and B's four masters
  -- are write traffic, so every number measured before this
  -- described a pattern only subsystem A issues.
  m01_axi_awvalid <= awvalid(1);
  awready(1) <= m01_axi_awready;
  m01_axi_awaddr  <= awaddr(65 downto 33);
  -- AXI3 again: 4-bit AWLEN, truncated HERE for the same reason
  -- ARLEN is.  A burst is at most 16 beats in EITHER direction.
  m01_axi_awlen   <= awlen(11 downto 8);
  m01_axi_awid    <= (others => '0');
  m01_axi_awsize  <= awsize(5 downto 3);
  m01_axi_awburst <= awburst(3 downto 2);
  m01_axi_wvalid  <= wvalid(1);
  wready(1) <= m01_axi_wready;
  m01_axi_wdata   <= wdata(511 downto 256);
  m01_axi_wstrb   <= wstrb(63 downto 32);
  m01_axi_wlast   <= wlast(1);
  bvalid(1) <= m01_axi_bvalid;
  m01_axi_bready  <= bready(1);
  bresp(3 downto 2) <= m01_axi_bresp;
  -- BID is returned and ignored: every burst uses ID 0, so there
  -- is nothing to demultiplex.  Note the HBM SAXI port has NO WID
  -- (checked against the IP's own port list, not assumed) -- it
  -- does not support write interleaving, which is exactly why one
  -- ID and in-order data is the only legal way to drive it.

  -- port 2
  m02_axi_arvalid <= arvalid(2);
  arready(2) <= m02_axi_arready;
  m02_axi_araddr  <= araddr(98 downto 66);
  -- AXI3: 4-bit ARLEN.  hbm_tg's register is 8-bit and protocol
  -- agnostic; anything above 15 would silently wrap, so it is
  -- truncated HERE, where the protocol is known.
  m02_axi_arlen   <= arlen(19 downto 16);
  m02_axi_arid    <= (others => '0');
  m02_axi_arsize  <= arsize(8 downto 6);
  m02_axi_arburst <= arburst(5 downto 4);
  m02_axi_rready  <= rready(2);
  rvalid(2) <= m02_axi_rvalid;
  rlast(2)  <= m02_axi_rlast;
  rresp(5 downto 4) <= m02_axi_rresp;
  -- write channel, live as of 2026-08-25.  It was tied off while the
  -- instrument was read-only; C 2.5's 2R+1W and B's four masters
  -- are write traffic, so every number measured before this
  -- described a pattern only subsystem A issues.
  m02_axi_awvalid <= awvalid(2);
  awready(2) <= m02_axi_awready;
  m02_axi_awaddr  <= awaddr(98 downto 66);
  -- AXI3 again: 4-bit AWLEN, truncated HERE for the same reason
  -- ARLEN is.  A burst is at most 16 beats in EITHER direction.
  m02_axi_awlen   <= awlen(19 downto 16);
  m02_axi_awid    <= (others => '0');
  m02_axi_awsize  <= awsize(8 downto 6);
  m02_axi_awburst <= awburst(5 downto 4);
  m02_axi_wvalid  <= wvalid(2);
  wready(2) <= m02_axi_wready;
  m02_axi_wdata   <= wdata(767 downto 512);
  m02_axi_wstrb   <= wstrb(95 downto 64);
  m02_axi_wlast   <= wlast(2);
  bvalid(2) <= m02_axi_bvalid;
  m02_axi_bready  <= bready(2);
  bresp(5 downto 4) <= m02_axi_bresp;
  -- BID is returned and ignored: every burst uses ID 0, so there
  -- is nothing to demultiplex.  Note the HBM SAXI port has NO WID
  -- (checked against the IP's own port list, not assumed) -- it
  -- does not support write interleaving, which is exactly why one
  -- ID and in-order data is the only legal way to drive it.

  -- port 3
  m03_axi_arvalid <= arvalid(3);
  arready(3) <= m03_axi_arready;
  m03_axi_araddr  <= araddr(131 downto 99);
  -- AXI3: 4-bit ARLEN.  hbm_tg's register is 8-bit and protocol
  -- agnostic; anything above 15 would silently wrap, so it is
  -- truncated HERE, where the protocol is known.
  m03_axi_arlen   <= arlen(27 downto 24);
  m03_axi_arid    <= (others => '0');
  m03_axi_arsize  <= arsize(11 downto 9);
  m03_axi_arburst <= arburst(7 downto 6);
  m03_axi_rready  <= rready(3);
  rvalid(3) <= m03_axi_rvalid;
  rlast(3)  <= m03_axi_rlast;
